// Event Bus - In-memory publish/subscribe system
type EventCallback = (payload: any) => void;

class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach((callback) => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event handler for ${event}:`, error);
        }
      });
    }
  }

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

export const eventBus = new EventBus();

// User Service - Manages user data
import { randomUUID } from "crypto";

interface User {
  id: string;
  name: string;
  email: string;
}

class UserService {
  private store: Map<string, User> = new Map();

  /**
   * Create a new user
   */
  create(name: string, email: string): User {
    const user: User = {
      id: randomUUID(),
      name,
      email,
    };
    this.store.set(user.id, user);
    return user;
  }

  /**
   * Get user by ID
   */
  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  /**
   * Get all users
   */
  getAll(): User[] {
    return Array.from(this.store.values());
  }

  /**
   * Update a user
   */
  update(id: string, updates: Partial<User>): User | undefined {
    const user = this.store.get(id);
    if (!user) return undefined;

    const updated = { ...user, ...updates, id };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a user
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

export const userService = new UserService();

// Project Service - Manages projects and project members
import { randomUUID } from "crypto";

interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

class ProjectService {
  private store: Map<string, Project> = new Map();

  /**
   * Create a new project
   */
  create(name: string, description: string): Project {
    const project: Project = {
      id: randomUUID(),
      name,
      description,
      memberIds: [],
    };
    this.store.set(project.id, project);
    return project;
  }

  /**
   * Get project by ID
   */
  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  /**
   * Get all projects
   */
  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  /**
   * Update a project
   */
  update(id: string, updates: Partial<Project>): Project | undefined {
    const project = this.store.get(id);
    if (!project) return undefined;

    const updated = { ...project, ...updates, id };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a project
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Add a member to a project
   */
  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  /**
   * Remove a member from a project
   */
  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    project.memberIds = project.memberIds.filter((id) => id !== userId);
    return project;
  }
}

export const projectService = new ProjectService();

// Task Service - Manages tasks
import { randomUUID } from "crypto";
import { eventBus } from "../event-bus";

type TaskStatus = "todo" | "in-progress" | "done";

interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

class TaskService {
  private store: Map<string, Task> = new Map();

  /**
   * Create a new task
   */
  create(
    title: string,
    description: string,
    projectId: string,
    assigneeId?: string
  ): Task {
    const task: Task = {
      id: randomUUID(),
      title,
      description,
      status: "todo",
      assigneeId: assigneeId || null,
      projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  /**
   * Get task by ID
   */
  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  /**
   * Get all tasks
   */
  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  /**
   * Get tasks by project
   */
  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  /**
   * Update a task
   */
  update(id: string, updates: Partial<Task>): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const updated = { ...task, ...updates, id };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a task
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Assign a task to a user
   */
  assign(taskId: string, assigneeId: string): Task | undefined {
    const task = this.store.get(taskId);
    if (!task) return undefined;

    task.assigneeId = assigneeId;
    this.store.set(taskId, task);

    // Publish event
    eventBus.publish("task.assigned", {
      taskId,
      taskTitle: task.title,
      assigneeId,
    });

    return task;
  }

  /**
   * Change task status (forward only: todo → in-progress → done)
   */
  changeStatus(taskId: string, newStatus: TaskStatus): Task | undefined {
    const task = this.store.get(taskId);
    if (!task) return undefined;

    const statusOrder = ["todo", "in-progress", "done"];
    const currentIndex = statusOrder.indexOf(task.status);
    const newIndex = statusOrder.indexOf(newStatus);

    // Only allow forward transitions
    if (newIndex <= currentIndex) {
      throw new Error(
        `Cannot transition from ${task.status} to ${newStatus}. Only forward transitions are allowed.`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(taskId, task);

    // Publish event
    eventBus.publish("task.statusChanged", {
      taskId,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }
}

export const taskService = new TaskService();

// Comment Service - Manages comments on tasks
import { randomUUID } from "crypto";
import { eventBus } from "../event-bus";
import { taskService } from "./task-service";
import { userService } from "./user-service";

interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: Date;
}

class CommentService {
  private store: Map<string, Comment> = new Map();

  /**
   * Create a new comment
   */
  create(taskId: string, authorId: string, body: string): Comment {
    const task = taskService.getById(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }

    const author = userService.getById(authorId);
    if (!author) {
      throw new Error(`User ${authorId} not found`);
    }

    const comment: Comment = {
      id: randomUUID(),
      taskId,
      authorId,
      body,
      createdAt: new Date(),
    };
    this.store.set(comment.id, comment);

    // Publish event
    eventBus.publish("comment.added", {
      commentId: comment.id,
      taskId,
      taskTitle: task.title,
      authorId,
      authorName: author.name,
    });

    return comment;
  }

  /**
   * Get comment by ID
   */
  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  /**
   * Get comments by task
   */
  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values())
      .filter((comment) => comment.taskId === taskId)
      .sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime());
  }

  /**
   * Delete a comment
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

export const commentService = new CommentService();

// Notification Service - Manages notifications
import { randomUUID } from "crypto";
import { eventBus } from "../event-bus";

interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: Date;
}

class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor() {
    // Subscribe to events
    this.setupSubscriptions();
  }

  private setupSubscriptions(): void {
    // Subscribe to task.assigned
    eventBus.subscribe("task.assigned", (payload) => {
      const { taskId, taskTitle, assigneeId } = payload;
      this.createNotification(
        assigneeId,
        `You have been assigned to task: ${taskTitle}`
      );
    });

    // Subscribe to task.statusChanged
    eventBus.subscribe("task.statusChanged", (payload) => {
      const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload;
      if (assigneeId) {
        this.createNotification(
          assigneeId,
          `Task "${taskTitle}" status changed from ${oldStatus} to ${newStatus}`
        );
      }
    });

    // Subscribe to comment.added
    eventBus.subscribe("comment.added", (payload) => {
      const { taskId, taskTitle, authorName, authorId } = payload;
      // Notification should go to the task assignee, but we'll need to look up the task
      // For now, we'll create a general comment notification
      // The router will need to find who is assigned to this task
      eventBus.publish("notification.commentAdded", {
        taskTitle,
        authorName,
        authorId,
        payload,
      });
    });
  }

  /**
   * Create a notification for a user
   */
  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  /**
   * Get notifications for a user
   */
  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values())
      .filter((notif) => notif.userId === userId)
      .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
  }

  /**
   * Mark a notification as read
   */
  markAsRead(notificationId: string): Notification | undefined {
    const notification = this.store.get(notificationId);
    if (!notification) return undefined;

    notification.read = true;
    return notification;
  }

  /**
   * Internal method to handle comment notifications
   * Called by router when needed
   */
  createCommentNotification(taskId: string, authorName: string): void {
    // This is a helper for the router to create notifications for task assignees
    // when a comment is added
  }
}

